import { defineConfig } from "vitest/config";
import { resolve } from "path";
import type { Plugin } from "vite";
import { svelteTesting } from "@testing-library/svelte/vite";
import { svelte } from "@sveltejs/vite-plugin-svelte";

const APP_ENV_STUB = resolve("./vitest.app-env.ts");
const PUBLIC_ENV_STUB = resolve("./vitest.env.ts");

const envStubPlugin = (): Plugin => ({
  name: "vitest-sveltekit-env-stub",
  enforce: "pre",
  resolveId(id) {
    // `$app/env` and the public env modules are generated by SvelteKit's Vite plugin,
    // which Vitest does not run. Resolve them explicitly so imports coming from
    // SvelteKit's own runtime files resolve too.
    if (id === "$app/env") return APP_ENV_STUB;
    if (id === "$app/env/public" || id === "$app/env/private")
      return PUBLIC_ENV_STUB;
    if (id === "$env/static/public" || id === "$env/dynamic/public")
      return PUBLIC_ENV_STUB;
    return null;
  },
});

export default defineConfig({
  plugins: [envStubPlugin(), svelte(), svelteTesting()],
  test: {
    include: ["src/**/*.{test,spec}.{ts,js}"],
    globals: true,
    environment: "jsdom",
    server: {
      deps: {
        // SvelteKit's runtime is ESM that imports virtual `$app/*` specifiers; inline it
        // so those imports are resolved by our aliases instead of Node.
        inline: [/@sveltejs\/kit/],
      },
    },
    setupFiles: ["./vitest.setup.ts"],
    testTimeout: 10000,
    hookTimeout: 10000,
    coverage: {
      provider: "v8",
      reporter: ["text", "lcov", "html"],
      include: ["src/lib/**/*.ts"],
      exclude: [
        "src/lib/api/types/**",
        "src/lib/components/ui/**",
        "**/*.d.ts",
        "**/index.ts",
        "**/*.test.ts",
        "**/*.spec.ts",
      ],
      thresholds: {
        "src/lib/utils/**": {
          lines: 70,
          functions: 70,
          branches: 60,
          statements: 70,
        },
        "src/lib/api/endpoints/**": {
          lines: 90,
          functions: 90,
          branches: 85,
          statements: 90,
        },
        "src/lib/stores/**": {
          lines: 90,
          functions: 90,
          branches: 80,
          statements: 90,
        },
        "src/lib/services/**": {
          lines: 90,
          functions: 90,
          branches: 85,
          statements: 90,
        },
      },
    },
  },
  resolve: {
    // JSdom tests run in Node; without pinning the condition order, packages whose
    // exports map marks Node-only entrypoints as `browser: null` fail to resolve.
    conditions: ["node", "import", "module", "default"],
    alias: [
      // `$app/env*` resolve to Vitest stubs: the real modules require the SvelteKit
      // client payload (`__SVELTEKIT_PAYLOAD__`) which Vitest never bootstraps.
      { find: /^\$app\/env$/, replacement: resolve("./vitest.app-env.ts") },
      { find: /^\$app\/env\/public$/, replacement: resolve("./vitest.env.ts") },
      {
        find: /^\$env\/static\/public$/,
        replacement: resolve("./vitest.env.ts"),
      },
      {
        find: /^\$env\/dynamic\/public$/,
        replacement: resolve("./vitest.env.ts"),
      },
      { find: "$lib", replacement: resolve("./src/lib") },
      { find: "$components", replacement: resolve("./src/lib/components") },
      { find: "$stores", replacement: resolve("./src/lib/stores") },
      { find: "$api", replacement: resolve("./src/lib/api") },
      { find: "$services", replacement: resolve("./src/lib/services") },
      { find: "$utils", replacement: resolve("./src/lib/utils") },
      {
        find: /^\$app$/,
        replacement: resolve("./node_modules/@sveltejs/kit/src/runtime/app"),
      },
      {
        find: /^\$app\//,
        replacement: `${resolve("./node_modules/@sveltejs/kit/src/runtime/app")}/`,
      },
    ],
  },
});
